const vg=drawingContext; const grd=vg.createRadialGradient(W/2,Hh*0.52,u*0.25, W/2,Hh*0.52,u*0.85);
grd.addColorStop(0,'rgba(255,255,255,1)'); grd.addColorStop(1,'rgba('+(st==='noir'?'40,40,55':'60,40,70')+',1)');
